CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nom VARCHAR(255), prenom VARCHAR(255), email VARCHAR(255) UNIQUE, password VARCHAR(255), role VARCHAR(255));
CREATE TABLE payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, stripe_payment_intent_id VARCHAR(255) UNIQUE, email VARCHAR(255), amount DOUBLE PRECISION, currency VARCHAR(255), status VARCHAR(255));
CREATE TABLE annonces (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, titre VARCHAR(255), description VARCHAR(4000), type_annonce VARCHAR(255), statut VARCHAR(255), image_url VARCHAR(255), model3d_url VARCHAR(255), user_id BIGINT REFERENCES users(id), payment_id BIGINT UNIQUE REFERENCES payments(id));
CREATE TABLE showrooms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nom VARCHAR(255), description VARCHAR(4000), user_id BIGINT REFERENCES users(id));
CREATE TABLE showroom_images (showroom_id BIGINT NOT NULL REFERENCES showrooms(id), image_data TEXT);
CREATE TABLE vehicules (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, marque VARCHAR(255), modele VARCHAR(255), annee INTEGER NOT NULL, prix DOUBLE PRECISION NOT NULL, couleur VARCHAR(255), showroom_id BIGINT REFERENCES showrooms(id));
CREATE TABLE news_items (id VARCHAR(255) PRIMARY KEY, title VARCHAR(300) NOT NULL, summary TEXT, image_url VARCHAR(600), source_name VARCHAR(100) NOT NULL, source_url VARCHAR(600) NOT NULL, published_at TIMESTAMP WITH TIME ZONE, unique_key VARCHAR(120) NOT NULL UNIQUE);
CREATE INDEX idx_news_published ON news_items(published_at);
